UPDATE object_storage_quota
SET used_bytes = used_bytes + #{sizeBytes}, object_count = object_count + 1
WHERE workspace_id = #{workspaceId}

UPDATE object_storage_quota
SET used_bytes = used_bytes - #{sizeBytes}, object_count = object_count - 1
WHERE workspace_id = #{workspaceId}
  AND used_bytes >= #{sizeBytes}
  AND object_count > 0
